class Solution {
public:
    string validIPAddress(string queryIP) {
        int n = queryIP.size();

        int dotCount = 0, colonCount = 0;
        for (char c : queryIP) {
            if (c == '.') dotCount++;
            else if (c == ':') colonCount++;
        }

        if (dotCount == 3) {
            int i = 0, segCount = 0;
            while (i <= n) {
                int j = i;
                while (j < n && queryIP[j] != '.') j++;
                int len = j - i;
                if (len == 0 || len > 3) return "Neither";
                if (len > 1 && queryIP[i] == '0') return "Neither";
                int val = 0;
                for (int k = i; k < j; k++) {
                    if (queryIP[k] < '0' || queryIP[k] > '9') return "Neither";
                    val = val * 10 + (queryIP[k] - '0');
                }
                if (val > 255) return "Neither";
                segCount++;
                if (j == n) break;
                i = j + 1;
            }
            return segCount == 4 ? "IPv4" : "Neither";
        }

        if (colonCount == 7) {
            int i = 0, segCount = 0;
            while (i <= n) {
                int j = i;
                while (j < n && queryIP[j] != ':') j++;
                int len = j - i;
                if (len == 0 || len > 4) return "Neither";
                for (int k = i; k < j; k++) {
                    char c = queryIP[k];
                    if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')))
                        return "Neither";
                }
                segCount++;
                if (j == n) break;
                i = j + 1;
            }
            return segCount == 8 ? "IPv6" : "Neither";
        }

        return "Neither";
    }
};
